GS_ADD([{"id":"a-nz-eoi","reg":"Oceania","mk":"NZ","mkt":"New Zealand","auth":"DIA","cat":"Licensing","date":"2026-07-17","v":"official","t":"New Zealand opens expressions of interest for online casino licences","d":"The window closed on 14 August. Up to 15 licences are on offer.","b":["The Department of Internal Affairs said on 17 July that expressions of interest for online casino licences were open. The window closed on 14 August 2026. Up to 15 licences are available. Each covers one brand and its platforms, runs for up to three years and can be renewed for five more. No one can hold more than three.","Providers that have not applied by 1 December 2026 must stop offering online casino gambling in New Zealand. Those with an application under review can keep operating but cannot advertise until a decision is made. A provider whose application is declined must leave the market."],"src":[["DIA, Online Gambling for Providers","https://www.dia.govt.nz/Online-Gambling-for-Providers","o"],["DIA, Online Gambling Resources","https://www.dia.govt.nz/Online-Gambling-Resources","o"]],"archive":true,"es":{"mkt":"Nueva Zelanda","auth":"DIA","t":"Nueva Zelanda abre la fase de manifestaciones de interés para licencias de casino online","d":"El plazo cerró el 14 de agosto. Se ofrecen hasta 15 licencias.","b":["El Department of Internal Affairs anunció el 17 de julio la apertura de la fase de manifestaciones de interés para licencias de casino online. El plazo cerró el 14 de agosto de 2026. Hay hasta 15 licencias disponibles. Cada una cubre una marca y sus plataformas, dura hasta tres años y puede renovarse por otros cinco. Nadie puede tener más de tres.","Los proveedores que no hayan presentado solicitud antes del 1 de diciembre de 2026 deberán dejar de ofrecer casino online en Nueva Zelanda. Quienes tengan una solicitud en revisión pueden seguir operando, pero no pueden hacer publicidad hasta que se resuelva. Un proveedor cuya solicitud sea denegada deberá salir del mercado."]},"ru":{"mkt":"Новая Зеландия","auth":"DIA","t":"Новая Зеландия начала прием заявок о заинтересованности в лицензиях онлайн-казино","d":"Прием завершился 14 августа. Будет выдано до 15 лицензий.","b":["Министерство внутренних дел 17 июля сообщило об открытии приема заявок о заинтересованности в получении лицензий онлайн-казино. Прием завершился 14 августа 2026 года. Доступно до 15 лицензий. Каждая распространяется на один бренд и его платформы, выдается на срок до трех лет и может быть продлена еще на пять. Никто не может иметь более трех лицензий.","Поставщики, не подавшие заявку до 1 декабря 2026 года, должны прекратить предлагать онлайн-казино в Новой Зеландии. Те, чьи заявки находятся на рассмотрении, могут продолжать работу, но не могут вести рекламу до принятия решения. Поставщик, получивший отказ, должен уйти с рынка."]}},{"id":"a-nz-regs","reg":"Oceania","mk":"NZ","mkt":"New Zealand","auth":"DIA","cat":"Safer gambling","date":"2026-07-03","v":"official","t":"New Zealand online casino regulations take effect","d":"Players must be able to set limits, and credit is banned.","b":["The Online Casino Gambling Regulations 2026 were made on 2 June and took effect on 3 July. Operators must let players set daily, weekly or monthly limits on time, deposits and spend. A request to raise or remove a limit can only take effect after at least 24 hours.","Players must be able to set a break of at least 5 minutes after 60 minutes of continuous play. Self-exclusion must take effect within 24 hours of the request. Operators cannot accept any payment method that involves a credit contract."],"src":[["Online Casino Gambling Regulations 2026 (SR 2026/169)","https://www.legislation.govt.nz/secondary-legislation/pco-drafted/2026/169/en/latest/","o"],["DIA, Online Gambling for Providers","https://www.dia.govt.nz/Online-Gambling-for-Providers","o"]],"archive":true,"es":{"mkt":"Nueva Zelanda","auth":"DIA","t":"Entra en vigor el reglamento de casino online de Nueva Zelanda","d":"Los jugadores deben poder fijar límites y se prohíbe el crédito.","b":["El Online Casino Gambling Regulations 2026 se aprobó el 2 de junio y entró en vigor el 3 de julio. Los operadores deben permitir a los jugadores fijar límites diarios, semanales o mensuales de tiempo, depósitos y gasto. Una solicitud para subir o eliminar un límite solo puede aplicarse tras al menos 24 horas.","Los jugadores deben poder fijar una pausa de al menos 5 minutos tras 60 minutos de juego continuo. La autoexclusión debe aplicarse en un plazo de 24 horas desde la solicitud. Los operadores no pueden aceptar ningún medio de pago que implique un contrato de crédito."]},"ru":{"mkt":"Новая Зеландия","auth":"DIA","t":"В Новой Зеландии вступили в силу правила для онлайн-казино","d":"Игроки должны иметь возможность устанавливать лимиты, кредит запрещен.","b":["Правила об онлайн-казино 2026 года были приняты 2 июня и вступили в силу 3 июля. Операторы обязаны позволять игрокам устанавливать дневные, недельные или месячные лимиты на время, депозиты и расходы. Запрос на повышение или отмену лимита может вступить в силу не ранее чем через 24 часа.","Игроки должны иметь возможность установить перерыв не менее 5 минут после 60 минут непрерывной игры. Самоисключение должно вступать в силу в течение 24 часов после запроса. Операторы не могут принимать способы оплаты, связанные с кредитным договором."]}},{"id":"a-au-bet365","reg":"Oceania","mk":"AU","mkt":"Australia","auth":"AUSTRAC","cat":"Payments & AML","date":"2026-07-06","v":"official","t":"bet365 agrees to overhaul AML systems under AUSTRAC undertaking","d":"The undertaking followed an AUSTRAC investigation that began after an independent audit.","b":["bet365 entered a legally binding enforceable undertaking with AUSTRAC to overhaul its anti-money laundering program. It must set up an ongoing risk assessment and improve how it detects and reports suspicious matters. Breaching the undertaking can lead to civil penalties. The AUSTRAC page has no date; the date comes from press."],"src":[["AUSTRAC","https://www.austrac.gov.au/news-and-media/news/bet365-overhaul-aml-systems-under-austrac-enforceable-undertaking","o"],["Asgam, 7 Jul 2026","https://asgam.com/2026/07/07/sports-betting-giant-bet365-enters-enforceable-undertaking-with-austrac-to-overhaul-aml-systems/","p"]],"archive":true,"es":{"mkt":"Australia","auth":"AUSTRAC","t":"bet365 se compromete a reformar sus sistemas de PBC/AML ante AUSTRAC","d":"El compromiso llega tras una investigación de AUSTRAC iniciada después de una auditoría independiente.","b":["bet365 suscribió con AUSTRAC un compromiso vinculante jurídicamente exigible para reformar su programa de prevención del blanqueo de capitales. Debe implantar una evaluación de riesgos continua y mejorar la detección y comunicación de operaciones sospechosas. El incumplimiento del compromiso puede dar lugar a sanciones civiles. La página de AUSTRAC no indica fecha; la fecha procede de la prensa."]},"ru":{"mkt":"Австралия","auth":"AUSTRAC","t":"bet365 обязалась перестроить системы ПОД/ФТ по соглашению с AUSTRAC","d":"Обязательство последовало за расследованием AUSTRAC, начатым после независимого аудита.","b":["bet365 приняла перед AUSTRAC юридически обязывающее обязательство с принудительной силой перестроить свою программу ПОД/ФТ (противодействие отмыванию доходов). Компания должна ввести постоянную оценку рисков и улучшить выявление подозрительных операций и сообщение о них. Нарушение обязательства может повлечь гражданско-правовые санкции. На странице AUSTRAC дата не указана, она взята из прессы."]}},{"id":"a-au-nicc-chair","reg":"Oceania","mk":"AU","mkt":"Australia","auth":"NICC","cat":"Licensing","date":"2026-07-09","v":"official","t":"NSW casino regulator's chief commissioner and a commissioner to leave","d":"Both leave in November 2026. The government is seeking successors.","b":["The NICC said its chief commissioner and one commissioner will leave in November 2026. Their terms were due to end on 24 May 2026 but were extended by six months. The NSW Government is running an expression of interest process for both seats."],"src":[["NICC, 9 Jul 2026","https://www.nicc.nsw.gov.au/news-and-media-releases/nicc-commissioners-to-complete-terms-after-decade-of-service-to-nsw","o"]],"archive":true,"es":{"mkt":"Australia","auth":"NICC","t":"El comisionado jefe y un comisionado del regulador de casinos de NSW dejarán el cargo","d":"Ambos se marchan en noviembre de 2026. El Gobierno busca sustitutos.","b":["La NICC informó de que su comisionado jefe y un comisionado dejarán el cargo en noviembre de 2026. Sus mandatos debían terminar el 24 de mayo de 2026, pero se prorrogaron seis meses. El Gobierno de NSW ha abierto un proceso de manifestaciones de interés para ambos puestos."]},"ru":{"mkt":"Австралия","auth":"NICC","t":"Главный комиссар и один из комиссаров регулятора казино Нового Южного Уэльса покинут посты","d":"Оба уйдут в ноябре 2026 года. Правительство ищет преемников.","b":["NICC сообщила, что ее главный комиссар и один из комиссаров покинут посты в ноябре 2026 года. Их полномочия должны были истечь 24 мая 2026 года, но были продлены на шесть месяцев. Правительство Нового Южного Уэльса проводит отбор кандидатов на обе должности."]}},{"id":"a-ie-remote","reg":"Europe","mk":"IE","mkt":"Ireland","auth":"GRAI","cat":"Licensing","date":"2026-07-01","v":"official","t":"Ireland's first GRAI remote betting licences take effect","d":"Licensees must verify age, refuse credit and close accounts on request.","b":["Licences from the Gambling Regulatory Authority of Ireland for remote betting and remote betting intermediaries took effect on 1 July 2026. Licensees must verify age, pay out winnings, refuse credit and credit cards, and close accounts on request. In-person betting licences follow later in 2026, and gaming, lottery, B2B and charity licences open through 2027 and 2028."],"src":[["GRAI","https://www.grai.ie/news/commencement-of-gambling-regulatory-authority-of-ireland-remote-betting-licences","o"],["EEG","https://eegaming.org/latest-news/2026/07/06/142060/grai-starts-issuing-remote-betting-licences/","p"]],"archive":true,"es":{"mkt":"Irlanda","auth":"GRAI","t":"Entran en vigor las primeras licencias de apuestas remotas de la GRAI en Irlanda","d":"Los titulares de licencia deben verificar la edad, rechazar el crédito y cerrar cuentas a petición del cliente.","b":["Las licencias de la Gambling Regulatory Authority of Ireland para apuestas remotas e intermediarios de apuestas remotas entraron en vigor el 1 de julio de 2026. Los titulares de licencia deben verificar la edad, pagar los premios, rechazar el crédito y las tarjetas de crédito y cerrar cuentas a petición del cliente. Las licencias de apuestas presenciales llegarán más adelante en 2026, y las de juego, lotería, B2B y entidades benéficas se abrirán a lo largo de 2027 y 2028."]},"ru":{"mkt":"Ирландия","auth":"GRAI","t":"В Ирландии вступили в силу первые лицензии GRAI на дистанционные ставки","d":"Лицензиаты должны проверять возраст, отказывать в кредите и закрывать счета по запросу.","b":["Лицензии Управления по регулированию азартных игр Ирландии (GRAI) на дистанционные ставки и посредничество в дистанционных ставках вступили в силу 1 июля 2026 года. Лицензиаты обязаны проверять возраст, выплачивать выигрыши, отказывать в кредите и не принимать кредитные карты, а также закрывать счета по запросу. Лицензии на ставки в наземных пунктах последуют позднее в 2026 году, а прием заявок на лицензии на азартные игры, лотереи, B2B и благотворительные лицензии откроется в 2027 и 2028 годах."]}},{"id":"a-nl-polymarket","reg":"Europe","mk":"NL","mkt":"Netherlands","auth":"KSA","cat":"Enforcement","date":"2026-07-08","v":"official","t":"Dutch regulator collects €420,000 from Polymarket's operator","d":"The company broke a penalty order of January 2026.","b":["Adventure One QSS Inc., which runs Polymarket, broke a KSA penalty order dated 20 January 2026, so €420,000 in penalties became payable. The KSA decided on collection on 19 May and rejected the company's objection on 23 June. The company can still appeal to court."],"src":[["KSA, Adventure One QSS Inc. (Polymarket)","https://kansspelautoriteit.nl/adventure-one-qss-inc-polymarket","o"]],"archive":true,"es":{"mkt":"Países Bajos","auth":"KSA","t":"El regulador neerlandés cobra 420.000 euros al operador de Polymarket","d":"La empresa incumplió una orden con multa coercitiva de enero de 2026.","b":["Adventure One QSS Inc., que gestiona Polymarket, incumplió una orden con multa coercitiva de la KSA de fecha 20 de enero de 2026, por lo que pasaron a ser exigibles 420.000 euros. La KSA acordó el cobro el 19 de mayo y desestimó la reclamación de la empresa el 23 de junio. La empresa aún puede recurrir ante los tribunales."]},"ru":{"mkt":"Нидерланды","auth":"KSA","t":"Нидерландский регулятор взыскивает 420 000 евро с оператора Polymarket","d":"Компания нарушила предписание под угрозой штрафа от января 2026 года.","b":["Adventure One QSS Inc., управляющая Polymarket, нарушила предписание KSA под угрозой штрафа от 20 января 2026 года, поэтому штрафы в размере 420 000 евро стали подлежащими уплате. KSA приняла решение о взыскании 19 мая и отклонила возражение компании 23 июня. Компания еще может обжаловать решение в суде."]}},{"id":"a-uk-evolution","reg":"Europe","mk":"GB","mkt":"Great Britain","auth":"Gambling Commission","cat":"Payments & AML","date":"2026-07-23","v":"official","t":"Evolution pays £4.75 million over games on unlicensed sites","d":"Its games appeared on six unlicensed websites used by UK consumers.","b":["Evolution Malta Holding Limited agreed to pay £4.75 million. Its games appeared on six unlicensed websites that UK consumers visited in large numbers between December 2023 and November 2024, supplied through two operators without a Commission licence. The Commission found its money laundering risk assessment, policies and customer due diligence were inadequate."],"src":[["Gambling Commission, 23 Jul 2026","https://www.gamblingcommission.gov.uk/news/article/evolution-malta-holding-limited-to-pay-gbp4-75m","o"]],"archive":true,"es":{"mkt":"Gran Bretaña","auth":"Gambling Commission","t":"Evolution pagará 4,75 millones de libras por sus juegos en webs sin licencia","d":"Sus juegos aparecieron en seis webs sin licencia utilizadas por consumidores del Reino Unido.","b":["Evolution Malta Holding Limited aceptó pagar 4,75 millones de libras. Sus juegos aparecieron en seis webs sin licencia que consumidores del Reino Unido visitaron de forma masiva entre diciembre de 2023 y noviembre de 2024, suministrados a través de dos operadores sin licencia de la Commission. La Commission concluyó que su evaluación del riesgo de blanqueo de capitales, sus políticas y su diligencia debida eran inadecuadas."]},"ru":{"mkt":"Великобритания","auth":"Gambling Commission","t":"Evolution заплатит 4,75 млн фунтов стерлингов из-за игр на нелицензированных сайтах","d":"Ее игры появлялись на шести нелицензированных сайтах, которыми пользовались британские потребители.","b":["Evolution Malta Holding Limited согласилась заплатить 4,75 млн фунтов стерлингов. Ее игры появлялись на шести нелицензированных сайтах, которые британские потребители массово посещали с декабря 2023 года по ноябрь 2024 года. Игры поставлялись через двух операторов без лицензии Комиссии. Комиссия установила, что оценка рисков отмывания денег, политики и процедуры надлежащей проверки клиентов компании были недостаточными."]}},{"id":"a-fr-aml","reg":"Europe","mk":"FR","mkt":"France","auth":"ANJ","cat":"Payments & AML","date":"2026-07-08","v":"official","t":"France issues first AML sanction against a licensed operator","d":"The operator ignored asset-freeze rules and had no internal procedures.","b":["In the ANJ's first anti-money laundering case before the sanctions commission, decided on 8 July, the operator was found to have ignored asset-freeze rules, had no internal procedures and had not informed the economy minister. The commission fined the operator, a director and the compliance officer, and imposed a suspended two-month operating ban. The operator and amounts were not disclosed."],"src":[["ANJ, 21 Sep 2026","https://anj.fr/lutte-contre-le-blanchiment-de-capitaux-une-premiere-sanction-de-la-commission-nationale-des-sanctions","o"]],"archive":true,"es":{"mkt":"Francia","auth":"ANJ","t":"Francia impone la primera sanción de PBC/AML a un operador con licencia","d":"El operador ignoró las normas de congelación de activos y carecía de procedimientos internos.","b":["En el primer caso de prevención del blanqueo de capitales de la ANJ ante su comisión de sanciones, resuelto el 8 de julio, se determinó que el operador había ignorado las normas de congelación de activos, carecía de procedimientos internos y no había informado al ministro de Economía. La comisión multó al operador, a un directivo y al responsable de cumplimiento, e impuso una prohibición de operar de dos meses en suspenso. No se revelaron ni el operador ni los importes."]},"ru":{"mkt":"Франция","auth":"ANJ","t":"Франция впервые наказала лицензированного оператора за нарушения ПОД/ФТ","d":"Оператор игнорировал правила о заморозке активов и не имел внутренних процедур.","b":["В первом деле ANJ о ПОД/ФТ (противодействие отмыванию доходов), рассмотренном комиссией по санкциям и решенном 8 июля, было установлено, что оператор игнорировал правила о заморозке активов, не имел внутренних процедур и не уведомлял министра экономики. Комиссия оштрафовала оператора, одного из руководителей и сотрудника по комплаенсу, а также наложила условный запрет на деятельность сроком на два месяца. Название оператора и суммы не раскрываются."]}},{"id":"a-fr-500k","reg":"Europe","mk":"FR","mkt":"France","auth":"ANJ","cat":"Safer gambling","date":"2026-07-10","v":"official","t":"France fines an online operator €500,000 over at-risk players","d":"The operator failed to spot the risk for nearly all of 30 sampled players.","b":["ANJ decision no. 2026-031 followed a hearing on 30 June. In a sample of 30 at-risk players from October 2023 to March 2024, the operator failed to spot the risk for nearly all of them and did not apply graduated support. The operator was not named. The decision can be appealed to the Conseil d'État within two months."],"src":[["ANJ, published 15 Jul 2026","https://anj.fr/sanction-de-500-000-e-operateur-de-jeux-dargent-en-ligne-pour-manquements","o"]],"archive":true,"es":{"mkt":"Francia","auth":"ANJ","t":"Francia multa con 500.000 euros a un operador online por los jugadores de riesgo","d":"El operador no detectó el riesgo en casi ninguno de los 30 jugadores de la muestra.","b":["La decisión de la ANJ n.º 2026-031 siguió a una audiencia celebrada el 30 de junio. En una muestra de 30 jugadores de riesgo de octubre de 2023 a marzo de 2024, el operador no detectó el riesgo en casi ninguno y no aplicó un acompañamiento gradual. No se identificó al operador. La decisión puede recurrirse ante el Conseil d'État en un plazo de dos meses."]},"ru":{"mkt":"Франция","auth":"ANJ","t":"Франция оштрафовала онлайн-оператора на 500 000 евро из-за игроков группы риска","d":"Оператор не выявил риск почти у всех из 30 игроков в выборке.","b":["Решение ANJ № 2026-031 принято после слушания 30 июня. В выборке из 30 игроков группы риска за период с октября 2023 года по март 2024 года оператор не выявил риск почти ни у одного из них и не применял поэтапные меры поддержки. Название оператора не раскрывается. Решение может быть обжаловано в Государственном совете (Conseil d'État) в течение двух месяцев."]}},{"id":"a-jm-machines","reg":"Caribbean","mk":"JM","mkt":"Jamaica","auth":"BGLC","cat":"Technology","date":"2026-07-01","v":"official","t":"Jamaica to bring in central monitoring for gaming machines","d":"The Betting, Gaming and Lotteries Commission will pick a provider through a request for proposals.","b":["Jamaica's Betting, Gaming and Lotteries Commission says it will introduce a central monitoring system for the gaming machine sector as part of wider reforms. It will issue a request for proposals to choose a provider, which will deploy and run the system under the Commission's oversight.","The Executive Director said the system will make it easier to identify, track and trace machines. He linked this to recent cases of suspected stolen equipment. Operators that have not finished the compliance process were urged to do so quickly, and the Commission says it will give guidance."],"src":[["Jamaica Information Service, 1 Jul 2026","https://jis.gov.jm/bglc-says-introduction-of-cms-will-strengthen-transparency-and-accountability/","o"],["Jamaica Gleaner, 30 Mar 2026","https://jamaica-gleaner.com/article/news/20260330/gaming-machines-spike-sparks-bglc-upgrade-oversight","p"]],"archive":true,"es":{"mkt":"Jamaica","auth":"BGLC","t":"Jamaica implantará un sistema de control central de las máquinas de juego","d":"La Betting, Gaming and Lotteries Commission elegirá un proveedor mediante una solicitud de propuestas.","b":["La Betting, Gaming and Lotteries Commission de Jamaica afirma que introducirá un sistema de control central para el sector de las máquinas de juego, dentro de una reforma más amplia. Publicará una solicitud de propuestas para elegir un proveedor, que desplegará y gestionará el sistema bajo la supervisión de la Commission.","El director ejecutivo señaló que el sistema facilitará la identificación, el seguimiento y la trazabilidad de las máquinas, y lo vinculó a casos recientes de presunto robo de equipos. Se instó a los operadores que no han terminado el proceso de cumplimiento a hacerlo con rapidez, y la Commission afirma que ofrecerá orientación."]},"ru":{"mkt":"Ямайка","auth":"BGLC","t":"Ямайка введет централизованный мониторинг игровых автоматов","d":"Комиссия по ставкам, азартным играм и лотереям выберет поставщика через запрос предложений.","b":["Комиссия по ставкам, азартным играм и лотереям Ямайки (BGLC) сообщает, что в рамках более широких реформ введет систему централизованного мониторинга в секторе игровых автоматов. Она объявит запрос предложений для выбора поставщика, который развернет систему и будет управлять ею под надзором Комиссии.","Исполнительный директор заявил, что система упростит идентификацию и отслеживание автоматов. Он связал это с недавними случаями предполагаемого хищения оборудования. Операторов, не завершивших процедуру проверки соответствия, призвали сделать это быстрее, Комиссия обещает предоставить разъяснения."]}},{"id":"a-bs-accounts","reg":"Caribbean","mk":"BS","mkt":"Bahamas","auth":"Gaming Board","cat":"Payments & AML","date":"2026-07-14","v":"official","t":"Bahamas bars non-gaming use of player accounts","d":"Players were depositing and withdrawing money without gaming.","b":["The Gaming Board for The Bahamas found players depositing money into gaming house accounts and withdrawing it without any gaming. Notice No. 1 of 2026 says such accounts are only for authorised gaming, and other use may lead to investigation and regulatory action."],"src":[["Gaming Board, 14 Jul 2026","https://www.gamingboardbahamas.com/use-of-patron-accounts-held-with-licensed-gaming-house-operators/","o"]],"archive":true,"es":{"mkt":"Bahamas","auth":"Gaming Board","t":"Bahamas prohíbe usar las cuentas de jugador para fines ajenos al juego","d":"Los jugadores depositaban y retiraban dinero sin jugar.","b":["La Gaming Board for The Bahamas detectó que algunos jugadores depositaban dinero en cuentas de casas de juego y lo retiraban sin jugar. El Aviso n.º 1 de 2026 establece que estas cuentas son solo para el juego autorizado y que cualquier otro uso puede dar lugar a una investigación y a medidas regulatorias."]},"ru":{"mkt":"Багамские Острова","auth":"Gaming Board","t":"Багамские Острова запретили использовать игровые счета не для игры","d":"Игроки вносили и выводили деньги, не делая ставок.","b":["Игорный совет Багамских Островов (Gaming Board) выявил, что игроки вносили деньги на счета в игорных заведениях и выводили их, не участвуя в игре. Согласно уведомлению № 1 от 2026 года, такие счета предназначены только для разрешенной игры. Иное использование может повлечь проверку и меры регулятора."]}},{"id":"a-es-reform","reg":"Europe","mk":"ES","mkt":"Spain","auth":"DGOJ","cat":"Advertising","date":"2026-07-21","v":"official","t":"Spain starts meetings on reform of the Gambling Law","d":"The reform covers ID and payment checks, illegal gambling and celebrity ads.","b":["The DGOJ began meetings with the more than 50 groups that commented on its consultation on reforming Law 13/2011. The reform targets stronger identity and payment checks, action against illegal gambling, rules on celebrities and influencers in ads, and new player protection tools."],"src":[["DGOJ, 21 Jul 2026","https://www.ordenacionjuego.es/novedades/dgoj-inicia-ronda-reuniones-entidades-han-presentado-aportaciones-reforma-ley-juego","o"]],"archive":true,"es":{"mkt":"España","auth":"DGOJ","t":"España inicia reuniones sobre la reforma de la Ley del Juego","d":"La reforma abarca los controles de identidad y de pagos, el juego ilegal y la publicidad con famosos.","b":["La DGOJ inició reuniones con los más de 50 colectivos que presentaron comentarios a su consulta pública sobre la reforma de la Ley 13/2011. La reforma busca reforzar los controles de identidad y de pagos, actuar contra el juego ilegal, regular la presencia de famosos e influencers en la publicidad y crear nuevas herramientas de protección del jugador."]},"ru":{"mkt":"Испания","auth":"DGOJ","t":"Испания начала встречи по реформе закона об азартных играх","d":"Реформа охватывает проверку личности и платежей, нелегальные азартные игры и рекламу с участием знаменитостей.","b":["DGOJ начала встречи с более чем 50 организациями, направившими замечания в ходе общественного обсуждения реформы Закона 13/2011. Реформа предусматривает усиление проверки личности и платежей, борьбу с нелегальными азартными играми, правила участия знаменитостей и инфлюенсеров в рекламе и новые инструменты защиты игроков."]}},{"id":"a-br-ads","reg":"Latin America","mk":"BR","mkt":"Brazil","auth":"SPA-MF","cat":"Advertising","date":"2026-07-10","v":"official","t":"Brazil requires Finance Ministry warnings on betting ads","d":"From 17 July 2026, betting ads must carry one of three set warnings covering at least 10% of the ad.","b":["Portaria SPA/MF 1.964 and Interministerial Portaria 73, published in the official gazette on 10 July 2026, tighten the rules on fixed-odds betting ads. Each ad must show one of three Finance Ministry warnings: that betting can cause addiction, that it makes you lose money, or that it is not an investment.","The warning must be clear, horizontal and take up at least 10% of the ad. The rules apply from 17 July 2026.","The interministerial ordinance, signed by the Finance and Justice ministries and the government communications office, makes everyone involved in spreading an ad responsible for following the rules. Ads may not mislead, target under-18s or promote unlicensed brands, and pundits may not urge people to bet on a given event."],"src":[["Agência Gov, 10 Jul 2026","https://agenciagov.ebc.com.br/noticias/202607/ministerio-da-fazenda-amplia-exigencias-de-publicidade-de-apostas-no-pais","o"]],"archive":true,"es":{"mkt":"Brasil","auth":"SPA-MF","t":"Brasil exige advertencias del Ministerio de Hacienda en los anuncios de apuestas","d":"Desde el 17 de julio de 2026, los anuncios de apuestas deben incluir una de tres advertencias fijadas que ocupe al menos el 10% del anuncio.","b":["La Portaria SPA/MF 1.964 y la Portaria Interministerial 73, publicadas en el boletín oficial el 10 de julio de 2026, endurecen las normas sobre publicidad de apuestas de cuota fija. Cada anuncio debe mostrar una de tres advertencias del Ministerio de Hacienda: que apostar puede causar adicción, que hace perder dinero o que no es una inversión.","La advertencia debe ser clara, horizontal y ocupar al menos el 10% del anuncio. Las normas se aplican desde el 17 de julio de 2026.","La ordenanza interministerial, firmada por los ministerios de Hacienda y de Justicia y la secretaría de comunicación del Gobierno, hace responsable de cumplir las normas a todos los que intervienen en la difusión de un anuncio. Los anuncios no pueden ser engañosos, dirigirse a menores de 18 años ni promocionar marcas sin licencia, y los comentaristas no pueden animar a apostar en un evento concreto."]},"ru":{"mkt":"Бразилия","auth":"SPA-MF","t":"Бразилия обязала размещать в рекламе ставок предупреждения Минфина","d":"С 17 июля 2026 года реклама ставок должна содержать одно из трех установленных предупреждений площадью не менее 10% рекламы.","b":["Portaria SPA/MF 1.964 и Межведомственная Portaria 73, опубликованные в официальном вестнике 10 июля 2026 года, ужесточают правила рекламы ставок с фиксированными коэффициентами. Каждая реклама должна содержать одно из трех предупреждений Министерства финансов: ставки могут вызывать зависимость, ведут к потере денег или не являются инвестицией.","Предупреждение должно быть четким, горизонтальным и занимать не менее 10% площади рекламы. Правила применяются с 17 июля 2026 года.","Межведомственный приказ подписали Министерство финансов, Министерство юстиции и правительственная служба коммуникаций. Он возлагает ответственность за соблюдение правил на всех участников распространения рекламы. Реклама не может вводить в заблуждение, быть нацелена на лиц младше 18 лет или продвигать нелицензированные бренды. Экспертам запрещено призывать делать ставки на конкретное событие."]}},{"id":"jm-casino","reg":"Caribbean","mk":"JM","mkt":"Jamaica","auth":"Casino Gaming Commission","cat":"Licensing","date":"2026-07-29","v":"official","brief":true,"t":"Jamaica issues its first casino operator's licence","d":"Adamas Grand Casino in Hanover must meet surveillance, AML and other conditions before it opens.","b":["The Casino Gaming Commission granted Jamaica's first casino gaming operator's licence to Adamas Grand Casino Limited, for a casino at the Princess Grand Jamaica Resort in Green Island, Hanover. Spanish group Grupo Orenes will run it under a management agreement. Before opening, the licensee must put in place approved internal controls, surveillance, responsible gaming, AML and counter-terrorism financing systems, and link to the Commission's gaming monitoring system. The project is valued at about US$800 million."],"src":[["Casino Gaming Commission, 29 Jul 2026","https://www.cgc.gov.jm/casino-gaming-commission-issues-jamaicas-first-casino-operators-licence-to-adamas-grand/","o"],["NY Carib News, 19 Oct 2026","https://nycaribnews.com/jamaica-first-casino-sets-february-2027-for-opening/","p"]],"archive":true,"es":{"mkt":"Jamaica","auth":"Casino Gaming Commission","t":"Jamaica concede su primera licencia de operador de casino","d":"Adamas Grand Casino, en Hanover, debe cumplir requisitos de videovigilancia, PBC/AML y otras condiciones antes de abrir.","b":["La Casino Gaming Commission concedió la primera licencia de operador de casino de Jamaica a Adamas Grand Casino Limited, para un casino en el Princess Grand Jamaica Resort de Green Island, en Hanover. El grupo español Grupo Orenes lo gestionará mediante un contrato de gestión. Antes de abrir, el titular debe implantar controles internos aprobados y sistemas de videovigilancia, juego responsable, prevención del blanqueo de capitales (PBC/AML) y de la financiación del terrorismo, y conectarse al sistema de supervisión del juego de la Comisión. El proyecto está valorado en unos 800 millones de dólares."]},"ru":{"mkt":"Ямайка","auth":"Casino Gaming Commission","t":"Ямайка выдала первую лицензию оператора казино","d":"Adamas Grand Casino в Хановере до открытия должно выполнить требования по видеонаблюдению, ПОД/ФТ и другие условия.","b":["Комиссия по игорной деятельности казино (Casino Gaming Commission) выдала первую на Ямайке лицензию оператора казино компании Adamas Grand Casino Limited для казино на курорте Princess Grand Jamaica Resort в Грин-Айленде, округ Хановер. Управлять казино по договору управления будет испанская группа Grupo Orenes. До открытия лицензиат должен внедрить утвержденные системы внутреннего контроля, видеонаблюдения, ответственной игры, ПОД/ФТ (противодействие отмыванию доходов) и противодействия финансированию терроризма, а также подключиться к системе мониторинга игр Комиссии. Проект оценивается примерно в 800 млн долларов США."]}},{"id":"a-cw-enfpol","reg":"Caribbean","mk":"CW","mkt":"Curaçao","auth":"CGA","cat":"Enforcement","date":"2026-07-17","v":"official","t":"Curaçao publishes its enforcement policy for online gaming","d":"The CGA sets out a phased approach that escalates from warnings to fines and licence revocation.","b":["The Curaçao Gaming Authority published a compliance and enforcement policy for online gaming, posted on its site on 17 July 2026. It applies the gaming ordinance in force since December 2024 and the island's AML and sanctions laws.","The policy works in three stages: prevention and information, risk-based supervision, then corrective measures and sanctions. Minor breaches normally get a warning or instruction. Serious or repeated breaches can lead to penalty orders, administrative fines, suspension or revocation of a licence, or referral to the prosecutor.","Top priorities are protecting minors and vulnerable people, fighting illegal gambling, preventing fraud and money laundering, and enforcing advertising and responsible gaming rules. The CGA says it will publish an annual enforcement report. Licensees can object to the CGA or appeal to the Court of First Instance."],"src":[["CGA, Compliance and Enforcement Policy (PDF)","https://gamingcontrol.spin-cdn.com/media/online_gaming/20260717_cga_compliance_and_enforcement_policy_online_gaming.pdf","o"],["CGA homepage","https://www.cga.cw","o"]],"archive":true,"es":{"mkt":"Curazao","auth":"CGA","t":"Curazao publica su política de control del juego online","d":"La CGA fija un enfoque por fases que va de las advertencias a las multas y la revocación de licencias.","b":["La Curaçao Gaming Authority publicó una política de cumplimiento y control para el juego online, colgada en su web el 17 de julio de 2026. Aplica la ordenanza de juego vigente desde diciembre de 2024 y las leyes de la isla sobre blanqueo de capitales y sanciones.","La política funciona en tres fases: prevención e información, supervisión basada en el riesgo y, por último, medidas correctoras y sanciones. Las infracciones leves suelen recibir una advertencia o una instrucción. Las graves o reiteradas pueden acarrear órdenes con multa coercitiva, multas administrativas, la suspensión o revocación de la licencia o la remisión a la fiscalía.","Las prioridades principales son proteger a los menores y a las personas vulnerables, combatir el juego ilegal, prevenir el fraude y el blanqueo de capitales y hacer cumplir las normas de publicidad y de juego responsable. La CGA dice que publicará un informe anual de control. Los titulares de licencia pueden presentar objeciones ante la CGA o recurrir ante el Tribunal de Primera Instancia."]},"ru":{"mkt":"Кюрасао","auth":"CGA","t":"Кюрасао опубликовал политику принуждения к исполнению в сфере онлайн-игр","d":"CGA описывает поэтапный подход: от предупреждений до штрафов и отзыва лицензии.","b":["Игорное управление Кюрасао (CGA) опубликовало политику соблюдения требований и принуждения к исполнению в сфере онлайн-игр, размещенную на его сайте 17 июля 2026 года. Она применяет постановление об играх, действующее с декабря 2024 года, а также законы острова о ПОД/ФТ и санкциях.","Политика предусматривает три этапа: профилактику и информирование, надзор на основе оценки рисков, затем корректирующие меры и санкции. За незначительные нарушения обычно выносится предупреждение или предписание. Серьезные или повторные нарушения могут повлечь предписания под угрозой штрафа, административные штрафы, приостановление или отзыв лицензии либо передачу дела прокурору.","Главные приоритеты: защита несовершеннолетних и уязвимых лиц, борьба с нелегальными азартными играми, предотвращение мошенничества и отмывания денег, а также соблюдение правил рекламы и ответственной игры. CGA сообщило, что будет публиковать ежегодный отчет о принудительных мерах. Лицензиаты могут подать возражение в CGA или обжаловать решение в суде первой инстанции."]}},{"id":"a-cw-winddown","reg":"Caribbean","mk":"CW","mkt":"Curaçao","auth":"CGA","cat":"Licensing","date":"2026-07-14","v":"official","t":"Curaçao issues wind-down rules for licence holders","d":"Revoked operators must stop taking bets at once. Player claims must still be paid.","b":["The CGA published instructions in July 2026 on winding down operations. They cover voluntary surrender, revocation as an enforcement measure, rejection of a second-term provisional licence or an indefinite licence, and dropping a single domain or app. Each case needs a signed wind-down report.","After a revocation, the company must stop using the CGA seal, stop taking new business and stop letting players wager, all with immediate effect. A company whose licence application is rejected faces the same limits and has six weeks to wind down.","Fees are not refunded. The end of a wind-down does not cancel player claims or debts, and the CGA says it will work with law enforcement if debts go unpaid."],"src":[["CGA, wind-down instructions (PDF)","https://gamingcontrol.spin-cdn.com/media/online_gaming_policies_and_guidelines/20261012_instructions_on_wind_down_of_operations_and_discontinuation_of_online_interfaces_by_license_holders_jul_202.pdf","o"],["CGA, online gaming regulation","https://www.cga.cw/regulation/online-gaming","o"],["AGB, 14 Jul 2026","https://agbrief.com/news/world/14/07/2026/curacao-issues-wind-down-rules-for-gaming-license-holders/","p"]],"archive":true,"es":{"mkt":"Curazao","auth":"CGA","t":"Curazao dicta normas para el cese de actividad de los titulares de licencia","d":"Los operadores con licencia revocada deben dejar de aceptar apuestas de inmediato. Las reclamaciones de los jugadores deben pagarse igualmente.","b":["La CGA publicó en julio de 2026 instrucciones sobre el cese ordenado de operaciones. Cubren la renuncia voluntaria, la revocación como medida sancionadora, el rechazo de una licencia provisional de segundo periodo o de una licencia indefinida y la baja de un solo dominio o aplicación. Cada caso requiere un informe de cese firmado.","Tras una revocación, la empresa debe dejar de usar el sello de la CGA, dejar de captar nuevo negocio y dejar de permitir apuestas a los jugadores, todo ello con efecto inmediato. Una empresa cuya solicitud de licencia sea rechazada afronta los mismos límites y dispone de seis semanas para cesar su actividad.","Las tasas no se reembolsan. El fin del cese de actividad no anula las reclamaciones de los jugadores ni las deudas, y la CGA afirma que colaborará con las fuerzas de seguridad si las deudas quedan impagadas."]},"ru":{"mkt":"Кюрасао","auth":"CGA","t":"Кюрасао утвердил правила сворачивания деятельности для держателей лицензий","d":"Операторы с отозванными лицензиями должны немедленно прекратить прием ставок. Требования игроков по-прежнему подлежат оплате.","b":["CGA в июле 2026 года опубликовало инструкции по сворачиванию деятельности. Они охватывают добровольный отказ от лицензии, отзыв лицензии в качестве меры принуждения, отказ в выдаче временной лицензии на второй срок или бессрочной лицензии, а также исключение отдельного домена или приложения. В каждом случае требуется подписанный отчет о сворачивании деятельности.","После отзыва лицензии компания должна с немедленным вступлением в силу прекратить использование печати CGA, прием новых клиентов и прием ставок от игроков. Компания, которой отказано в выдаче лицензии, подпадает под те же ограничения и должна свернуть деятельность в течение шести недель.","Уплаченные сборы не возвращаются. Завершение сворачивания деятельности не отменяет требований игроков и долгов, и CGA заявляет, что будет взаимодействовать с правоохранительными органами в случае неуплаты долгов."]}},{"id":"a-bd-act","reg":"Asia","mk":"BD","mkt":"Bangladesh","auth":"Parliament","cat":"Legislation","date":"2026-07-01","v":"official","t":"Bangladesh passes Gambling Prevention Act 2026","d":"Online betting offences carry up to 7 years in prison. The 1867 Act is repealed.","b":["Bangladesh's Gambling Prevention Act 2026 (Act No. 98 of 2026), dated 1 July 2026, took effect immediately and repeals the Public Gambling Act 1867. It makes taking part in gambling, online gambling and online betting an offence.","Online betting and operating as a bookmaker carry up to 7 years in prison, a fine of up to Tk 5 crore, or both. Online gambling carries up to 5 years and Tk 1 crore. Conventional gambling carries up to 2 years and Tk 200,000.","The government or an authority it names can block gambling websites, apps, domains, IP addresses and social media channels, including mirror sites. Courts can order bank, mobile money, payment gateway and crypto accounts used for gambling to be shut. Moving gambling money is treated as a predicate offence under the money laundering law."],"src":[["Bangladesh Ministry of Law, Act No. 98 of 2026","https://bdlaws.minlaw.gov.bd/act-details-1727.html?lang=en","o"],["Asia News Network","https://asianews.network/bangladesh-parliament-passes-anti-gambling-law/","p"]],"archive":true,"es":{"mkt":"Bangladés","auth":"Parlamento","t":"Bangladés aprueba la Ley de Prevención del Juego de 2026","d":"Los delitos de apuestas online conllevan hasta 7 años de prisión. Queda derogada la ley de 1867.","b":["La Ley de Prevención del Juego de 2026 de Bangladés (Ley n.º 98 de 2026), fechada el 1 de julio de 2026, entró en vigor de inmediato y deroga la Public Gambling Act 1867. Tipifica como delito participar en el juego, en el juego online y en las apuestas online.","Las apuestas online y la actividad como corredor de apuestas conllevan hasta 7 años de prisión, una multa de hasta 5 crore de takas (Tk) o ambas penas. El juego online conlleva hasta 5 años y 1 crore de takas. El juego convencional, hasta 2 años y 200.000 takas.","El Gobierno o una autoridad que designe pueden bloquear sitios web, aplicaciones, dominios, direcciones IP y canales en redes sociales de juego, incluidos los sitios espejo. Los tribunales pueden ordenar el cierre de cuentas bancarias, de dinero móvil, de pasarelas de pago y de criptomonedas usadas para el juego. Mover dinero del juego se considera delito subyacente según la ley de blanqueo de capitales."]},"ru":{"mkt":"Бангладеш","auth":"Парламент","t":"Бангладеш принял Закон о предотвращении азартных игр 2026 года","d":"За правонарушения в сфере онлайн-ставок грозит до 7 лет лишения свободы. Закон 1867 года отменен.","b":["Закон Бангладеш о предотвращении азартных игр 2026 года (Закон № 98 от 2026 года), датированный 1 июля 2026 года, вступил в силу немедленно и отменяет Закон о публичных азартных играх 1867 года. Он признает правонарушением участие в азартных играх, онлайн-азартных играх и онлайн-ставках.","За онлайн-ставки и букмекерскую деятельность грозит до 7 лет лишения свободы, штраф до 5 крор так или оба наказания. За онлайн-азартные игры грозит до 5 лет и штраф до 1 крора так. За обычные азартные игры грозит до 2 лет и штраф до 200 000 так.","Правительство или назначенный им орган может блокировать игорные сайты, приложения, домены, IP-адреса и каналы в социальных сетях, включая зеркала. Суды могут обязать закрыть банковские счета, счета мобильных денег, платежных шлюзов и криптовалютные счета, используемые для азартных игр. Перемещение средств от азартных игр рассматривается как предикатное преступление по закону об отмывании денег."]}},{"id":"a-ng-b2b","reg":"Africa","mk":"NG","mkt":"Nigeria","auth":"LSLGA","cat":"Enforcement","date":"2026-07-20","v":"official","t":"Lagos regulator puts B2B suppliers and payment firms under certification","d":"A six-month roadmap requires operators, platform vendors and payment providers to certify their systems or be disconnected.","b":["The Lagos State Lotteries and Gaming Authority published a notice on 20 July 2026 addressed to licensed operators, B2B providers and financial partners. Citing the November 2024 Supreme Court ruling on state control of gaming, it set out a technical overhaul under the state's 2021 gaming law, aimed at AML safeguards and traceable money flows.","Operators, B2B software and platform providers and payment service providers must join a registry census in the first two months. In months three to five they submit game source code, random number generators, online platforms, machines and payment gateways for audit. In month six, systems without a certificate are disconnected and the licence is revoked.","Older technical certificates from labs the authority does not recognise must be moved into the new framework. The authority also named a newly accredited testing laboratory."],"src":[["LSLGA, public notice 20 Jul 2026","https://lslga.org/official-public-notice-to-all-licensed-gaming-operators-b2b-providers-and-financial-partners/","o"],["Vanguard","https://www.vanguardngr.com/2026/08/one-judgment-thirty-six-rulebooks-the-compliance-bill-facing-nigerias-digital-gaming-operators/","p"]],"archive":true,"es":{"mkt":"Nigeria","auth":"LSLGA","t":"El regulador de Lagos somete a certificación a los proveedores B2B y las empresas de pagos","d":"Una hoja de ruta de seis meses obliga a operadores, proveedores de plataformas y proveedores de pagos a certificar sus sistemas o ser desconectados.","b":["La Lagos State Lotteries and Gaming Authority publicó el 20 de julio de 2026 un aviso dirigido a los operadores con licencia, los proveedores B2B y los socios financieros. Citando la sentencia del Tribunal Supremo de noviembre de 2024 sobre el control estatal del juego, fijó una reforma técnica en virtud de la ley de juego del estado de 2021, orientada a las salvaguardas de PBC/AML y a la trazabilidad de los flujos de dinero.","Los operadores, los proveedores B2B de software y plataformas y los proveedores de servicios de pago deben inscribirse en un censo registral en los dos primeros meses. Entre el tercer y el quinto mes deben presentar para auditoría el código fuente de los juegos, los generadores de números aleatorios, las plataformas online, las máquinas y las pasarelas de pago. En el sexto mes, los sistemas sin certificado se desconectan y se revoca la licencia.","Los certificados técnicos anteriores de laboratorios que la autoridad no reconoce deben trasladarse al nuevo marco. La autoridad también designó un laboratorio de pruebas recién acreditado."]},"ru":{"mkt":"Нигерия","auth":"LSLGA","t":"Регулятор Лагоса ввел сертификацию для B2B-поставщиков и платежных компаний","d":"Шестимесячная дорожная карта обязывает операторов, поставщиков платформ и платежных услуг сертифицировать свои системы под угрозой отключения.","b":["Управление лотерей и игр штата Лагос 20 июля 2026 года опубликовало уведомление для лицензированных операторов, B2B-поставщиков и финансовых партнеров. Сославшись на решение Верховного суда от ноября 2024 года о контроле штатов над играми, управление объявило техническую реформу в рамках закона штата об играх 2021 года, направленную на меры ПОД/ФТ и прослеживаемость денежных потоков.","Операторы, поставщики B2B-программ и платформ, а также поставщики платежных услуг должны пройти регистрационную перепись в первые два месяца. С третьего по пятый месяц они представляют на аудит исходный код игр, генераторы случайных чисел, онлайн-платформы, автоматы и платежные шлюзы. На шестом месяце системы без сертификата отключаются, а лицензия отзывается.","Прежние технические сертификаты лабораторий, которые управление не признает, должны быть переведены в новую систему. Управление также назвало новую аккредитованную испытательную лабораторию."]}},{"id":"a-cz-poly","reg":"Europe","mk":"CZ","mkt":"Czechia","auth":"Ministry of Finance","cat":"Enforcement","date":"2026-07-13","v":"official","t":"Czechia adds Polymarket to its list of unauthorised internet games","d":"The finance ministry listed polymarket.com on 13 July 2026.","b":["The Czech Ministry of Finance entered polymarket.com on its List of Unauthorised Internet Games on 13 July 2026. The ministry's published extract cites Section 84a(2)(a) of the Gambling Act as the ground.","Websites on the list must be blocked by internet providers under the Gambling Act. The published entry covers the website only and lists no payment account."],"src":[["Czech Ministry of Finance, List of Unauthorised Internet Games","https://mf.gov.cz/cs/kontrola-a-regulace/hazardni-hry/blokace-nepovolenych-internetovych-her/verejna-cast-seznamu-nepovolenych-internetovych-he","o"],["Deník","https://www.denik.cz/cesko/polymarket-v-cesku-konci/","p"]],"archive":true,"es":{"mkt":"Chequia","auth":"Ministerio de Finanzas","t":"Chequia incluye Polymarket en su lista de juegos por internet no autorizados","d":"El Ministerio de Finanzas incluyó polymarket.com en la lista el 13 de julio de 2026.","b":["El Ministerio de Finanzas checo inscribió polymarket.com en su Lista de Juegos por Internet No Autorizados el 13 de julio de 2026. El extracto publicado por el ministerio cita como fundamento la sección 84a(2)(a) de la Ley de Juego.","Según la Ley de Juego, los proveedores de internet deben bloquear los sitios web que figuran en la lista. La inscripción publicada afecta solo al sitio web y no incluye ninguna cuenta de pago."]},"ru":{"mkt":"Чехия","auth":"Министерство финансов","t":"Чехия внесла Polymarket в список несанкционированных интернет-игр","d":"Министерство финансов внесло polymarket.com в список 13 июля 2026 года.","b":["Министерство финансов Чехии 13 июля 2026 года внесло polymarket.com в Список несанкционированных интернет-игр. В опубликованной выписке министерства основанием указан раздел 84a(2)(a) Закона об азартных играх.","Согласно Закону об азартных играх, интернет-провайдеры обязаны блокировать сайты из этого списка. Опубликованная запись касается только сайта, платежные счета в ней не указаны."]}},{"id":"a-eu-amla-rbs","reg":"Europe","mk":"EU","mkt":"European Union","auth":"AMLA","cat":"Payments & AML","date":"2026-07-13","v":"official","t":"AMLA consults on how supervisors will risk-score non-financial firms, including gambling","d":"The draft standards set one EU method for rating money laundering risk. They would apply from 31 December 2028.","b":["The EU Anti-Money Laundering Authority consulted from 13 July to 27 September 2026 on draft technical standards under Article 40(2) of the AML Directive. They set how supervisors assess the inherent and residual risk of obliged entities in the non-financial sector.","AMLA's press release names gambling among the channels through which criminal money enters the economy. Each type of business gets its own data points, and smaller entities report fewer. A public hearing was held on 10 September, and the method would apply from 31 December 2028."],"src":[["AMLA, consultation page","https://www.amla.europa.eu/policy/public-consultations/consultation-draft-rts-assessment-inherent-and-residual-risk-profile-obliged-entities-non-financial_en","o"],["SBC News","https://sbcnews.co.uk/igaming/2026/07/14/eu-gambling-aml/","p"]],"archive":true,"es":{"mkt":"Unión Europea","auth":"AMLA","t":"La AMLA consulta cómo los supervisores puntuarán el riesgo de las empresas no financieras, incluido el juego","d":"El proyecto de normas fija un único método de la UE para calificar el riesgo de blanqueo de capitales. Se aplicaría a partir del 31 de diciembre de 2028.","b":["La Autoridad de Lucha contra el Blanqueo de Capitales de la UE (AMLA) sometió a consulta pública, del 13 de julio al 27 de septiembre de 2026, un proyecto de normas técnicas en virtud del artículo 40(2) de la Directiva AML. Las normas establecen cómo los supervisores evalúan el riesgo inherente y residual de los sujetos obligados del sector no financiero.","El comunicado de prensa de la AMLA menciona el juego entre los canales por los que el dinero de origen delictivo entra en la economía. Cada tipo de negocio tiene sus propios datos que reportar, y las entidades más pequeñas reportan menos. El 10 de septiembre se celebró una audiencia pública, y el método se aplicaría a partir del 31 de diciembre de 2028."]},"ru":{"mkt":"Европейский союз","auth":"AMLA","t":"AMLA обсуждает методику оценки рисков нефинансовых компаний, включая игорные","d":"Проект стандартов устанавливает единый для ЕС метод оценки риска отмывания денег. Он будет применяться с 31 декабря 2028 года.","b":["Европейское управление по противодействию отмыванию денег (AMLA) с 13 июля по 27 сентября 2026 года проводило общественное обсуждение проекта технических стандартов по статье 40(2) Директивы о ПОД/ФТ. Они определяют, как надзорные органы оценивают присущий и остаточный риск подотчетных субъектов нефинансового сектора.","В пресс-релизе AMLA азартные игры названы среди каналов, через которые преступные деньги попадают в экономику. Для каждого вида бизнеса предусмотрен свой набор показателей, небольшие субъекты отчитываются по меньшему их числу. Публичные слушания прошли 10 сентября, а методика будет применяться с 31 декабря 2028 года."]}},{"id":"a-it-agcom-rep","reg":"Europe","mk":"IT","mkt":"Italy","auth":"AGCOM","cat":"Advertising","date":"2026-07-14","v":"official","t":"AGCOM report records no gambling ad fines in 2025","d":"Fines and settlements under the gambling ad ban came to about €12.4 million in 2023 and €1.8 million in 2024, and zero in 2025.","b":["AGCOM's 2026 annual report puts fines and settlement payments under the gambling advertising ban at €0 for 2025. The figures were about €12.40 million in 2023 and €1.81 million in 2024.","The report notes that in July 2025 the Lazio administrative court asked the Constitutional Court to review the fixed minimum fine of €50,000 per breach in the 2018 Dignity Decree.","Two references to the EU Court of Justice are pending. Case C-421/24, involving Google, concerns a platform's liability when it knowingly partners with content creators. Case C-194/25, over a fine on LeoVegas, concerns whether Italy should have notified the ad ban under the EU technical rules directive."],"src":[["AGCOM, Relazione annuale 2026","https://www.agcom.it/pubblicazioni/relazioni-annuali/relazione-annuale-2026-sullattivita-svolta-e-sui-programmi-di","o"],["SiGMA","https://sigma.world/it/news/italia-relazione-agcom-2026-zero-sanzioni-pubblicita-sul-gioco/","p"]],"archive":true,"es":{"mkt":"Italia","auth":"AGCOM","t":"El informe de AGCOM no registra multas por publicidad de juego en 2025","d":"Las multas y pagos por acuerdo derivados de la prohibición de publicidad del juego sumaron unos 12,4 millones de euros en 2023 y 1,8 millones en 2024, y cero en 2025.","b":["El informe anual 2026 de AGCOM sitúa en 0 euros las multas y los pagos por acuerdo derivados de la prohibición de publicidad del juego en 2025. Las cifras fueron de unos 12,40 millones de euros en 2023 y 1,81 millones de euros en 2024.","El informe recuerda que en julio de 2025 el tribunal administrativo del Lacio pidió al Tribunal Constitucional que revisara la multa mínima fija de 50.000 euros por infracción prevista en el Decreto Dignidad de 2018.","Hay dos cuestiones prejudiciales pendientes ante el Tribunal de Justicia de la UE. El asunto C-421/24, que afecta a Google, trata de la responsabilidad de una plataforma cuando colabora a sabiendas con creadores de contenido. El asunto C-194/25, sobre una multa a LeoVegas, trata de si Italia debió notificar la prohibición publicitaria con arreglo a la directiva europea sobre reglamentaciones técnicas."]},"ru":{"mkt":"Италия","auth":"AGCOM","t":"AGCOM: в 2025 году штрафов за рекламу азартных игр не было","d":"Штрафы и выплаты по мировым соглашениям за нарушение запрета на рекламу азартных игр составили около 12,4 млн евро в 2023 году, 1,8 млн евро в 2024 году и ноль в 2025 году.","b":["Согласно годовому отчету AGCOM за 2026 год, сумма штрафов и выплат по мировым соглашениям за нарушение запрета на рекламу азартных игр в 2025 году составила 0 евро. В 2023 году она составляла около 12,40 млн евро, в 2024 году около 1,81 млн евро.","В отчете отмечается, что в июле 2025 года административный суд Лацио обратился в Конституционный суд с запросом о проверке фиксированного минимального штрафа в 50 000 евро за каждое нарушение, установленного «Декретом о достоинстве» 2018 года.","На рассмотрении Суда ЕС находятся два запроса. Дело C-421/24 с участием Google касается ответственности платформы, сознательно сотрудничающей с авторами контента. Дело C-194/25 о штрафе в отношении LeoVegas касается того, должна ли была Италия уведомить о запрете рекламы в соответствии с директивой ЕС о технических регламентах."]}},{"id":"a-pe-36","reg":"Latin America","mk":"PE","mkt":"Peru","auth":"MINCETUR","cat":"Enforcement","date":"2026-07-21","v":"official","t":"Peru blocks 36 unlicensed betting platforms","d":"MINCETUR also seized 39 slot machines at four illegal venues.","b":["Peru's trade and tourism ministry, MINCETUR, blocked 36 technology platforms offering remote games and sports betting to Peruvian users without authorisation, under Law 31557. Its gaming directorate worked with the transport and communications ministry.","In separate raids with the police and prosecutors, it seized 39 slot machines at four clandestine venues in Ancón, Pomalca and Cataos, and one more machine in Ancón that minors were using."],"src":[["El Peruano, 21 Jul 2026","https://elperuano.pe/noticia/300783-mincetur-bloquea-36-plataformas-de-juegos-a-distancia-y-apuestas-deportivas-que-operaban-sin-autorizacion","o"],["SoloAzar","https://www.soloazar.com/es/categoria/otros/mincetur-bloquea-36-plataformas-ilegales-de-apuestas-online","p"]],"archive":true,"es":{"mkt":"Perú","auth":"MINCETUR","t":"Perú bloquea 36 plataformas de apuestas sin licencia","d":"El MINCETUR también incautó 39 máquinas tragamonedas en cuatro locales ilegales.","b":["El Ministerio de Comercio Exterior y Turismo del Perú (MINCETUR) bloqueó 36 plataformas tecnológicas que ofrecían juegos a distancia y apuestas deportivas a usuarios peruanos sin autorización, en aplicación de la Ley 31557. Su dirección de juegos trabajó con el Ministerio de Transportes y Comunicaciones.","En operativos separados con la policía y la fiscalía, incautó 39 máquinas tragamonedas en cuatro locales clandestinos de Ancón, Pomalca y Cataos, y una máquina más en Ancón que utilizaban menores de edad."]},"ru":{"mkt":"Перу","auth":"MINCETUR","t":"Перу заблокировала 36 нелицензированных платформ ставок","d":"MINCETUR также изъяло 39 игровых автоматов в четырех нелегальных заведениях.","b":["Министерство внешней торговли и туризма Перу (MINCETUR) заблокировало 36 технологических платформ, предлагавших перуанским пользователям дистанционные игры и спортивные ставки без разрешения, на основании Закона 31557. Его игорная дирекция действовала совместно с Министерством транспорта и связи.","В ходе отдельных рейдов с полицией и прокуратурой министерство изъяло 39 игровых автоматов в четырех подпольных заведениях в Анконе, Помальке и Катаосе, а также еще один автомат в Анконе, которым пользовались несовершеннолетние."]}},{"id":"a-co-vat","reg":"Latin America","mk":"CO","mkt":"Colombia","auth":"Ministry of Finance","cat":"Tax","date":"2026-07-20","v":"official","t":"Colombia files tax bill to keep 19% VAT on online gambling","d":"The finance ministry estimates about COP 1.7 trillion from the measure in 2027.","b":["The government's tax reform bill, filed in the Chamber of Representatives as bill No. 004 of 2026, includes VAT at the general 19% rate on games of chance operated only online.","The explanatory memorandum notes that online gambling was taxed at 19% under the 2025 internal unrest emergency until 31 December 2025. The bill's revenue table puts the yield from the gambling measure at about COP 1.72 trillion in 2027, rising to about COP 2.05 trillion in 2030."],"src":[["Chamber of Representatives, bill 004/2026","https://www.camara.gov.co/wp-content/uploads/2026/07/proyectos-ley/documentos/proyecto-36102/P.L.004-2026SC-REFORMA-TRIBUTARIA.pdf","o"],["Minhacienda, Proyecto de Ley de Financiamiento","https://www.minhacienda.gov.co/w/proyecto-de-ley-de-financiamiento","o"],["Mundo Video","https://www.mundovideo.com.co/casinos-colombia-noticias/iva-permanente-al-juego-online-gobierno-petro-lleva-propuesta-ante-el-nuevo-congreso/","p"]],"archive":true,"es":{"mkt":"Colombia","auth":"Ministerio de Hacienda y Crédito Público","t":"Colombia radica un proyecto de ley tributaria para mantener el IVA del 19% al juego online","d":"El Ministerio de Hacienda calcula que la medida recaudará cerca de 1,7 billones de pesos en 2027.","b":["El proyecto de reforma tributaria del Gobierno, radicado en la Cámara de Representantes como proyecto de ley n.º 004 de 2026, incluye el IVA a la tarifa general del 19% sobre los juegos de suerte y azar operados exclusivamente por internet.","La exposición de motivos recuerda que el juego online tributó al 19% en virtud de la conmoción interior de 2025 hasta el 31 de diciembre de 2025. La tabla de recaudo del proyecto estima el rendimiento de la medida sobre el juego en cerca de 1,72 billones de pesos en 2027, que subiría a cerca de 2,05 billones de pesos en 2030."]},"ru":{"mkt":"Колумбия","auth":"Министерство финансов","t":"Колумбия внесла налоговый законопроект о сохранении НДС 19% на онлайн-азартные игры","d":"Министерство финансов оценивает поступления от этой меры примерно в 1,7 трлн колумбийских песо в 2027 году.","b":["Правительственный законопроект о налоговой реформе, внесенный в Палату представителей под № 004 от 2026 года, предусматривает НДС по общей ставке 19% на азартные игры, проводимые исключительно онлайн.","В пояснительной записке отмечается, что онлайн-азартные игры облагались налогом по ставке 19% в рамках чрезвычайного положения 2025 года в связи с внутренними беспорядками до 31 декабря 2025 года. Согласно таблице доходов законопроекта, поступления от этой меры составят около 1,72 трлн колумбийских песо в 2027 году и вырастут примерно до 2,05 трлн колумбийских песо в 2030 году."]}}]);
